sys_variable_value.value:
(function execute(inputs, outputs) {
    var doppel = new DoppelIOCImport();
    var result = doppel.getAlertById(inputs.alert_id);
    if (!result.success) {
        outputs.hit = false; outputs.error = result.error || '';
        return;
    }
    if (!result.data) {
        outputs.hit = false; outputs.error = '';
        return;
    }
    var a = result.data;
    outputs.hit = true;
    outputs.alert_id = a.id || '';
    outputs.brand = a.brand || '';
    outputs.product_type = a.product || '';
    outputs.queue_state = a.queue_state || '';
    outputs.entity_state = a.entity_state || '';
    outputs.doppel_link = a.doppel_link || '';
    outputs.error = '';
})(inputs, outputs);

